      z-index: 1;
    }

    .step.secondary .badge {
      background: rgba(59,130,246,0.12);
      border: 1px solid rgba(59,130,246,0.20);
      color: var(--accent-secondary);
    }

    .step h3 {
      font-size: 22px;
      font-weight: 650;
      z-index: 1;
    }

    .step p {
      margin-top: 4px;
      font-size: 16px;
      color: var(--text-secondary);
      line-height: 1.35;
      z-index: 1;
    }

    .dur {
      font-size: 16px;
      font-weight: 650;
      color: var(--text);
      padding: 10px 12px;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: rgba(0,0,0,0.16);
      z-index: 1;
      white-space: nowrap;
    }

    .arrow {
      height: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-secondary);
      opacity: 0.9;
    }

    .arrow svg { width: 18px; height: 18px; }

    /* Outcomes table */
    .table {
      width: 100%;
      border-collapse: collapse;
      overflow: hidden;
      border-radius: 14px;
      border: 1px solid var(--border);
      background: rgba(0,0,0,0.14);
    }

    .table th, .table td {
      padding: 14px 14px;
      font-size: 15px;
      border-bottom: 1px solid rgba(255,255,255,0.06);
      vertical-align: top;
    }

    .table th {
      text-align: left;
      color: var(--text-secondary);
      font-weight: 650;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      font-size: 13px;
      background: rgba(255,255,255,0.04);
    }

    .table tr:last-child td { border-bottom: none; }

    .delta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-weight: 700;
    }

    .delta.good { color: var(--positive); }
    .delta.bad { color: var(--negative); }

    /* Trade-offs */
    .trade-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 14px;
      margin-top: 12px;
    }

    .trade {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }

    .trade .box {
      padding: 16px 18px;
      border-radius: 14px;
      border: 1px solid var(--border);
      background: rgba(255,255,255,0.03);
    }

    .trade .box h4 {
      font-size: 16px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--text-secondary);
      font-weight: 700;
    }

    .trade .box ul {
      margin-top: 10px;
      padding-left: 18px;
      color: var(--text-secondary);
      font-size: 16px;
      line-height: 1.45;
    }

    .trade .box li { margin: 8px 0; }

    .foot {
      position: relative;
      z-index: 2;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 18px;
      align-items: center;
      padding: 18px 0 0;
      border-top: 1px solid rgba(255,255,255,0.08);
      color: var(--text-secondary);
      font-size: 14px;
    }

    .foot strong { color: var(--text); font-weight: 650; }

    .cite {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .cite span {
      padding: 8px 10px;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: rgba(255,255,255,0.03);
      color: var(--text-secondary);
    }

    /* Hidden helper for download */
    .download-target { width: var(--poster-w); height: var(--poster-h); }

    /* Ensure menu not captured unless desired */
    .hide-in-export .viz-menu { display: none !important; }

    /* Accessibility focus */
    :focus-visible { outline: 3px solid var(--accent); outline-offset: 4px; border-radius: 8px; }

    /* Print page setup */
    @page { margin: 0; }

  </style>
</head>
<body>
  <a href="#main-content" class="skip-link" style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;" onfocus="this.style.cssText='position:fixed;left:16px;top:16px;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;'" onblur="this.style.cssText='position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;'">Skip to content</a>

  <!-- MENU -->
  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <main id="main-content" role="main" class="download-target">
    <div class="poster" id="posterRoot" aria-label="IEEE Symposium on Security and Privacy poster">
      <div class="bg-atmos"></div>

      <section class="topbar" aria-label="Poster header">
        <header class="title-card animate">
          <div class="kicker"><span class="kicker-dot"></span> IEEE Symposium on Security and Privacy (S&P) • Bot Mitigation</div>
          <h1 class="title">Bot Mitigation at Scale: How Modern Web Security Services Protect Scientific Publishing Platforms</h1>
          <p class="subtitle">An analysis of how challenge-based verification systems safeguard high-value academic web properties against automated threats.</p>
          <div class="meta">
            <span class="pill">Case: www.science.org • DOI: <span style="font-variant-numeric: tabular-nums;">10.1126/science.add1585</span></span>
            <span class="pill">Key takeaway: challenge pipelines reduce scraping while maintaining availability</span>
          </div>
        </header>

        <aside class="big-metrics animate delay-1" aria-label="Key headline metrics">
          <div class="kpi" role="group" aria-label="Scraping reduction KPI">
            <div class="kpi-label"><span class="chip"></span> Reduction in scraping attempts (6 months)</div>
            <div class="kpi-value">85%</div>
            <div class="kpi-note">Unauthorized bulk scraping drops from ~1.2M/day to ~180k/day.</div>
          </div>
          <div class="kpi secondary" role="group" aria-label="Uptime KPI">
            <div class="kpi-label"><span class="chip"></span> Uptime under DDoS-level bot surges</div>
            <div class="kpi-value">99.97%</div>
            <div class="kpi-note">Sustained availability during ≥10× traffic surges at the edge.</div>
          </div>
        </aside>
      </section>

      <section class="content" aria-label="Main content sections">
        <!-- Threat landscape -->
        <section class="card animate delay-2" aria-label="Threat landscape">
          <div class="section-title">
            <h2>The Bot Threat Landscape for Academic Publishers</h2>
            <div class="objective">Scale + intent: nearly half of web requests are automated; a material fraction is malicious.</div>
          </div>

          <div class="threat-grid" role="list" aria-label="Threat headline stats">
            <div class="mini" role="listitem">
              <div class="lab">Estimated share of internet traffic from bots (2024)</div>
              <div class="val accent">~47%</div>
            </div>
            <div class="mini" role="listitem">
              <div class="lab">Malicious bot share of total bot traffic</div>
              <div class="val">30%</div>
            </div>
            <div class="mini" role="listitem">
              <div class="lab">High-value targets</div>
              <div class="val">DOIs, PDFs, datasets</div>
            </div>
            <div class="mini" role="listitem">
              <div class="lab">Common automated threats</div>
              <div class="val">Scraping, stuffing, DoS</div>
            </div>
          </div>

          <div class="chart-wrap" role="img" aria-label="Bot traffic composition chart">
            <canvas id="botShareChart" aria-label="Chart showing bots vs humans and malicious share" role="img"></canvas>
          </div>

          <p class="text-secondary" style="margin-top: 14px; font-size: 16px; line-height: 1.45;">
            Scientific publishing platforms host high-value intellectual property and attract automated collection attempts. The economic incentive (content resale, model training, competitive intelligence) turns open access endpoints into scraping magnets.
          </p>
        </section>

        <!-- Verification pipeline -->
        <section class="card animate delay-3" aria-label="Challenge-based verification pipeline">
          <div class="section-title">
            <h2>Challenge-Based Verification Pipeline</h2>
            <div class="objective">Sequential edge workflow: score risk, issue challenges, validate response, then forward verified sessions.</div>
          </div>

          <div class="pipeline" aria-label="Pipeline steps">
            <div class="step" role="group" aria-label="Step 1 request interception">
              <div class="badge">1</div>
              <div>
                <h3>Request interception at CDN edge</h3>
                <p>Incoming HTTP request is routed through an edge node before origin access.</p>
              </div>
              <div class="dur">&lt; 50 ms</div>
            </div>
            <div class="arrow" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14"/><path d="m19 12-7 7-7-7"/></svg>
            </div>
            <div class="step secondary" role="group" aria-label="Step 2 threat scoring">
              <div class="badge">2</div>
              <div>
                <h3>Threat scoring</h3>
                <p>IP reputation, TLS fingerprint, and behavioral signals produce a risk score.</p>
              </div>
              <div class="dur">~ 100 ms</div>
            </div>
            <div class="arrow" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14"/><path d="m19 12-7 7-7-7"/></svg>
            </div>
            <div class="step" role="group" aria-label="Step 3 challenge issuance">
              <div class="badge">3</div>
              <div>
                <h3>Challenge issuance</h3>
                <p>If risk exceeds threshold, serve JavaScript / CAPTCHA challenge.</p>
              </div>
              <div class="dur">~ 500 ms</div>
            </div>
            <div class="arrow" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14"/><path d="m19 12-7 7-7-7"/></svg>
            </div>
            <div class="step secondary" role="group" aria-label="Step 4 verification check">
              <div class="badge">4</div>
              <div>
                <h3>Verification check + tracing</h3>
                <p>Validate response; assign traceable identifier (e.g., Ray ID) for monitoring.</p>
              </div>
              <div class="dur">~ 200 ms</div>
            </div>
            <div class="arrow" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14"/><path d="m19 12-7 7-7-7"/></svg>
            </div>
            <div class="step" role="group" aria-label="Step 5 access grant">
              <div class="badge">5</div>
              <div>
                <h3>Access grant to origin</h3>
                <p>Forward verified session to the origin with a token; scripts without JS are blocked.</p>
              </div>
              <div class="dur">&lt; 50 ms</div>
            </div>
          </div>

          <div style="display:grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-top: 16px;">
            <div class="mini" role="group" aria-label="Legitimate user verification latency">
              <div class="lab">Average verification latency (legitimate)</div>
              <div class="val accent">&lt; 2 seconds</div>
            </div>
            <div class="mini" role="group" aria-label="Added page load overhead">
              <div class="lab">Average page-load overhead (verified sessions)</div>
              <div class="val">&lt; 150 ms</div>
            </div>
          </div>
        </section>

        <!-- Outcomes -->
        <section class="card animate delay-4" aria-label="Performance and security outcomes">
          <div class="section-title">
            <h2>Performance and Security Outcomes</h2>
            <div class="objective">Measured impact after CDN-level mitigation on a major science publisher.</div>
          </div>

          <div class="chart-wrap" style="height: 300px;" role="img" aria-label="Before vs after bar chart">
            <canvas id="beforeAfterChart" aria-label="Chart showing before vs after metrics" role="img"></canvas>
          </div>

          <table class="table" aria-label="Before and after mitigation table" style="margin-top: 14px;">
            <thead>
              <tr>
                <th>Metric</th>
                <th>Before</th>
                <th>After</th>
                <th>Effect</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Scraping attempts / day</td>
                <td style="font-variant-numeric: tabular-nums;">~1.2M</td>
                <td style="font-variant-numeric: tabular-nums;">~180k</td>
                <td><span class="delta good">↓ 85%</span></td>
              </tr>
              <tr>
                <td>Origin server load (CPU %)</td>
                <td style="font-variant-numeric: tabular-nums;">78%</td>
                <td style="font-variant-numeric: tabular-nums;">42%</td>
                <td><span class="delta good">↓ 46%</span></td>
              </tr>
              <tr>
                <td>Legitimate user complaints (monthly)</td>
                <td style="font-variant-numeric: tabular-nums;">1,200</td>
                <td style="font-variant-numeric: tabular-nums;">340</td>
                <td><span class="delta good">↓ 72%</span></td>
              </tr>
              <tr>
                <td>Uptime during bot surges</td>
                <td style="font-variant-numeric: tabular-nums;">98.5%</td>
                <td style="font-variant-numeric: tabular-nums;">99.97%</td>
                <td><span class="delta good">↑ +1.47pp</span></td>
              </tr>
            </tbody>
          </table>

          <p class="text-secondary" style="margin-top: 14px; font-size: 16px; line-height: 1.45;">
            Quantitative monitoring at the edge (including trace identifiers like Ray IDs) enables continuous tuning: tightening thresholds during surges while minimizing false positives for institutional users.
          </p>
        </section>

        <!-- Trade-offs -->
        <section class="card animate delay-5" aria-label="Usability vs security trade-offs">
          <div class="section-title">
            <h2>Usability vs. Security Trade-offs</h2>
            <div class="objective">Design for resilience without blocking legitimate researchers.</div>
          </div>

          <div class="trade-grid">
            <div class="trade" aria-label="Trade-off considerations">
              <div class="box" aria-label="Security priorities">
                <h4>Security requirements</h4>
                <ul>
                  <li>Block scripts lacking JS execution / automation hardening</li>
                  <li>Rate-limit scraping and credential stuffing</li>
                  <li>Absorb DDoS-level bot surges at the edge</li>
                  <li>Trace requests end-to-end for rapid incident response</li>
                </ul>
              </div>
              <div class="box" aria-label="Usability priorities">
                <h4>Usability constraints</h4>
                <ul>
                  <li>WCAG 2.1 compliant challenge experiences</li>
                  <li>Institutional allowlisting to avoid unnecessary friction</li>
                  <li>Transparent messaging (“Performing security verification…”) to preserve trust</li>
                  <li>Privacy-aware telemetry and clear disclosure of data practices</li>
                </ul>
              </div>
            </div>

            <div class="mini" aria-label="Reported friction">
              <div class="lab">Legitimate users reporting verification friction</div>
              <div class="val" style="color: var(--positive);">&lt; 0.3%</div>
            </div>

            <div class="mini" aria-label="Practical recommendation">
              <div class="lab">Operational recommendation</div>
              <div class="val">Treat verification as a control loop</div>
              <div class="lab">Measure → tune thresholds → monitor false positives → iterate.</div>
            </div>
          </div>

          <div style="margin-top: 14px; padding: 16px 18px; border-radius: 14px; border: 1px solid rgba(34,211,238,0.18); background: rgba(34,211,238,0.06);">
            <div style="display:flex; align-items:center; gap:12px;">
              <div style="width: 36px; height: 36px; border-radius: 12px; background: rgba(34,211,238,0.14); border: 1px solid rgba(34,211,238,0.24); display:grid; place-items:center; color: var(--accent);">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>
              </div>
              <div>
                <div style="font-weight: 750; font-size: 18px;">Key takeaways</div>
                <div class="text-secondary" style="font-size: 16px; line-height: 1.45; margin-top: 4px;">
                  Bot traffic is a massive, persistent threat to academic platforms. Edge verification pipelines can preserve near-perfect availability while sharply reducing bulk scraping.
                </div>
              </div>
            </div>
          </div>
        </section>
      </section>

      <footer class="foot" aria-label="Footer">
        <div>
          <strong>Poster focus:</strong> CDN-level, challenge-based verification for scientific publishing platforms • Audience: security researchers & practitioners
          <div style="margin-top: 6px;">Data summarized from a deployment case study (science publisher) and industry bot traffic estimates (2024).</div>
        </div>
        <div class="cite" aria-label="Key metrics list">
          <span>~47% traffic bots</span>
          <span>30% malicious bots</span>
          <span>&lt;2s verification</span>
          <span>85% scraping reduction</span>
          <span>99.97% uptime</span>
        </div>
      </footer>
    </div>
  </main>

  <script>
    // ===== Menu + theme =====
    function toggleMenu() {
      var dd = document.getElementById('vizMenuDropdown');
      dd.classList.toggle('open');
    }

    document.addEventListener('click', function(e) {
      var menu = document.querySelector('.viz-menu');
      if (!menu) return;
      if (!menu.contains(e.target)) {
        var dd = document.getElementById('vizMenuDropdown');
        if (dd) dd.classList.remove('open');
      }
    });

    var chartsBuilt = false;

    function applyThemeLabel() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.textContent = isDark ? '🌙' : '☀️';
      if (label) label.textContent = isDark ? 'Dark' : 'Light';
    }

    function cycleTheme() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      document.documentElement.className = isDark ? 'theme-light' : 'theme-dark';
      applyThemeLabel();
      if (chartsBuilt) buildCharts();
    }

    // ===== Chart manager (required guard patterns) =====
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var canvas = document.getElementById(canvasId);
          if (!canvas) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (canvas.chart) { canvas.chart.destroy(); delete canvas.chart; }
          canvas.setAttribute('role', 'img');
          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(canvas.getContext('2d'), config);
          canvas.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (err) {
          console.error('Error initializing chart ' + canvasId, err);
          return null;
        }
      }
    };

    function cssVar(name) {
      return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    }

    function buildCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }

      var gridColor = document.documentElement.classList.contains('theme-dark')
        ? 'rgba(234,240,255,0.08)'
        : 'rgba(11,18,32,0.08)';

      var tickColor = cssVar('--text-secondary') || (document.documentElement.classList.contains('theme-dark') ? 'rgba(234,240,255,0.68)' : 'rgba(11,18,32,0.70)');
      var textColor = cssVar('--text') || (document.documentElement.classList.contains('theme-dark') ? '#EAF0FF' : '#0b1220');
      var accent = cssVar('--accent') || '#22D3EE';
      var accent2 = cssVar('--accent-secondary') || '#3B82F6';

      // Pie: bots/humans + malicious share within bots
      ChartManager.safeInit('botShareChart', {
        type: 'doughnut',
        data: {
          labels: ['Bots (~47%)', 'Humans (~53%)'],
          datasets: [{
            data: [47, 53],
            backgroundColor: [
              'rgba(34,211,238,0.85)',
              document.documentElement.classList.contains('theme-dark') ? 'rgba(234,240,255,0.18)' : 'rgba(11,18,32,0.16)'
            ],
            borderColor: [
              'rgba(34,211,238,0.95)',
              document.documentElement.classList.contains('theme-dark') ? 'rgba(234,240,255,0.22)' : 'rgba(11,18,32,0.20)'
            ],
            borderWidth: 2,
            hoverOffset: 6
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          cutout: '68%',
          layout: { padding: 14 },
          plugins: {
            legend: {
              position: 'right',
              labels: { color: tickColor, boxWidth: 14, boxHeight: 14, padding: 14, font: { size: 13, weight: 500 } }
            },
            tooltip: {
              enabled: true,
              callbacks: {
                afterLabel: function(ctx) {
                  if (ctx.dataIndex === 0) return 'Malicious share of bots: 30%';
                  return '';
                }
              }
            }
          }
        }
      });

      // Bar: before vs after (scraping/day, CPU load, complaints, uptime)
      ChartManager.safeInit('beforeAfterChart', {
        type: 'bar',
        data: {
          labels: ['Scraping/day (k)', 'CPU load (%)', 'Complaints/mo', 'Uptime (%)'],
          datasets: [
            {
              label: 'Before',
              data: [1200, 78, 1200, 98.5],
              backgroundColor: 'rgba(244,63,94,0.25)',
              borderColor: 'rgba(244,63,94,0.55)',
              borderWidth: 2,
              borderRadius: 6
            },
            {
              label: 'After',
              data: [180, 42, 340, 99.97],
              backgroundColor: 'rgba(16,185,129,0.22)',
              borderColor: 'rgba(16,185,129,0.55)',
              borderWidth: 2,
              borderRadius: 6
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: 18 },
          scales: {
            x: {
              ticks: { color: tickColor, font: { size: 12, weight: 500 } },
              grid: { color: 'rgba(0,0,0,0)', borderColor: gridColor }
            },
            y: {
              beginAtZero: true,
              ticks: { color: tickColor, font: { size: 12, weight: 500 } },
              grid: { color: gridColor, borderColor: gridColor }
            }
          },
          plugins: {
            legend: { labels: { color: tickColor, font: { size: 12, weight: 600 } } },
            tooltip: { enabled: true }
          }
        }
      });

      // Add subtle title overlays using native text elements (keeps chart clean)
      chartsBuilt = true;
    }

    // ===== Export =====
    async function downloadImage() {
      var root = document.getElementById('posterRoot');
      if (!root) return;

      // Temporarily hide menu, ensure consistent background.
      document.body.classList.add('hide-in-export');

      try {
        var dataUrl = await window.htmlToImage.toPng(root, {
          pixelRatio: 2,
          backgroundColor: getComputedStyle(document.documentElement).getPropertyValue('--bg').trim() || '#070B12'
        });
        var link = document.createElement('a');
        link.download = 'final_poster.png';
        link.href = dataUrl;
        link.click();
      } catch (e) {
        console.error('Export failed', e);
      } finally {
