const path = require('path');
const puppeteer = require('puppeteer-core');

(async () => {
  const htmlPath = path.resolve(__dirname, 'final_poster.html');
  const outPath = path.resolve(__dirname, 'final_poster.png');

  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium-browser',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--font-render-hinting=medium'],
    defaultViewport: { width: 2480, height: 3508, deviceScaleFactor: 2 },
  });

  try {
    const page = await browser.newPage();

    // Allow local file access to /app assets.
    await page.goto('file://' + htmlPath, { waitUntil: 'networkidle0' });

    // Wait for charts to render.
    await page.waitForFunction(() => {
      const c1 = document.getElementById('botShareChart');
      const c2 = document.getElementById('beforeAfterChart');
      return !!(c1 && c2 && c1.chart && c2.chart);
    }, { timeout: 30000 });

    // Hide menu explicitly.
    await page.addStyleTag({ content: `.viz-menu{display:none !important;}` });

    const root = await page.$('#posterRoot');
    if (!root) throw new Error('posterRoot not found');

    await root.screenshot({ path: outPath });
  } finally {
    await browser.close();
  }
})();
